import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1191, own='cte_114.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 817 Precision Metal Manufacturing I ----
H("817.d.1.A",3,"A high school student interested in machining looks up which math courses, certifications and degrees a community college machining program requires. She is determining:","academic knowledge and skills required for postsecondary education and careers",["only her favorite foods","only her vacation plans","only the weather"],"Know requirements before choosing a path.")
H("817.d.1.A",4,"A student who wants to become a CNC programmer should plan to build strong skills in:","math, blueprint reading and computer applications",["only art history","only music theory","only cooking"],"CNC careers rely on these skills.")
H("817.d.1.B",3,"A shop manager says her customers expect parts delivered on time, to print and with a friendly response to problems. These are employer expectations that help:","foster positive customer satisfaction",["lower the shop's standards","avoid communication","reduce quality"],"Meeting expectations satisfies customers.")
H("817.d.1.B",4,"A machinist who notices a defect in a finished batch before shipping should:","report it so it can be corrected before the customer receives it",["hide it","ship it anyway","blame a coworker"],"Quality protects customers.")
H("817.d.1.C",3,"A new machinist arrives early, wears the required safety gear, follows shop procedures and treats coworkers respectfully. He is demonstrating:","professional standards required in the workplace",["casual habits","careless habits","random habits"],"Professionalism includes punctuality and respect.")
H("817.d.1.C",4,"Which habit best shows professionalism on a shop floor?","arriving on time and following safety procedures",["texting while operating a machine","skipping the safety meeting","leaving tools out"],"Reliability and safety.")
H("817.d.1.D",3,"A student writes down the certifications she wants in two years, the job she wants in five and the skills she needs to get there. She is evaluating:","personal career goals",["a recipe","a game score","a sports schedule"],"Goal setting guides planning.")
H("817.d.1.D",4,"A useful career goal is one that is:","specific and has steps and a timeline",["vague and undated","impossible to measure","secret from everyone"],"Specific goals can be tracked.")
H("817.d.1.E",3,"When the instructions for a job are unclear, a machinist asks the supervisor to restate the part number, quantity and finish before starting. She is communicating to:","clarify objectives and expectations in the workplace",["slow the shop down","confuse the supervisor","avoid work"],"Clear communication prevents errors.")
H("817.d.1.E",4,"The best time to ask a question about a job's requirements is:","before starting the work",["after the part is scrapped","never","after shipping"],"Asking early saves material.")
H("817.d.1.F",3,"A machine shop requires safety glasses on the floor, labels hazardous chemicals and posts emergency exits. These practices show skills related to:","health and safety in the workplace as specified by OSHA",["office decorating","company advertising","shift changes"],"OSHA sets workplace safety rules.")
H("817.d.1.F",4,"OSHA is the government agency that sets and enforces rules for:","workplace safety and health",["school lunches","road maps","sports leagues"],"Occupational Safety and Health Administration.")
H("817.d.2.A",3,"A machinist writes a clear one-page procedure telling the next operator how to set up a fixture, with numbered steps and the gauge to use. She is demonstrating:","technical writing skills for work requirements",["story writing","poetry","journal doodling"],"Technical writing is clear and exact.")
H("817.d.2.A",4,"Technical writing for a machine setup sheet should be:","clear, concise and in logical order",["flowery and vague","random and humorous","very long and unclear"],"Operators must follow it exactly.")
H("817.d.2.B",3,"A machinist uses algebra to solve for the feed rate, geometry to find a bolt-circle position and trigonometry to find an angled cut. He is demonstrating:","mathematical skills such as algebra, geometry and trigonometry",["only counting","only rounding","only guessing"],"Machining uses several kinds of math.")
H("817.d.2.B",4,"A bolt circle of four holes is laid out on a plate. The angle between adjacent holes is:","90 degrees",["45 degrees","60 degrees","120 degrees"],"360 ÷ 4 = 90.")
H("817.d.2.C",3,"A machinist reads a print with feature control frames that show flatness, perpendicularity and position tolerances for each surface. She is interpreting:","engineering drawings, including those with geometric dimensioning and tolerancing",["menu boards","bus maps","sports charts"],"GD&T defines form and position tolerances.")
H("817.d.2.C",4,"On a print, a feature control frame tells the machinist:","the geometric tolerance that applies to a feature",["the delivery date","the shop's address","the part's color"],"It specifies form, orientation or location.")
H("817.d.2.D",3,"A student looks at a print that shows a part from the front, top and right side and then at a picture that shows all three faces in one angled view. She is describing:","orthographic and isometric views of three-dimensional figures",["only 2D clip art","only photos","only sketches of faces"],"Ortho = separate views; iso = one 3D view.")
H("817.d.2.D",4,"A single drawing that shows the top, front and right faces of a part at once is called an:","isometric view",["end view","orthographic view","section view"],"Isometric shows three faces.")
H("817.d.2.E",3,"A machinist calculates the spindle speed for a 0.500-inch end mill cutting aluminum and checks that the answer is reasonable. She is evaluating:","mathematics as it applies to precision machining operations",["a poem","a painting","a song"],"Math drives cutting parameters.")
H("817.d.2.E",4,"Spindle speed (RPM) for a cutter is found by:","(cutting speed × 12) ÷ (π × cutter diameter)",["diameter plus length","length minus width","depth times feed only"],"RPM = (CS × 3.82) / D.")
H("817.d.2.F",3,"A machinist notes that cutting with a dull tool produces more heat and needs more force because of friction. He is discussing basic concepts of physics, such as:","friction, force and heat as applied to machining",["only light","only sound","only magnetism"],"Cutting converts force into heat.")
H("817.d.2.F",4,"The heat generated while cutting metal is mostly carried away by:","the chips and the cutting fluid",["the operator's hand","the floor","the ceiling"],"Chips remove most of the heat.")
H("817.d.3.A",3,"A student looks up a thread's pitch diameter in the handbook, checks a catalog for a recommended insert grade and a speeds-and-feeds app for a chart. She is examining:","resources found in recognized manufacturing reference materials",["blogs about music","fantasy novels","shopping flyers"],"Reference materials provide shop data.")
H("817.d.3.A",4,"A reliable reference for the dimensions of standard threads is:","a machinist's handbook",["a cookbook","a travel guide","a novel"],"Handbooks list thread data.")
H("817.d.3.B",3,"A machinist uses a chart to find that a 1/4-20 tap needs a #7 drill. He is demonstrating knowledge of:","the uses of reference charts such as tap drill charts",["decorating charts","school schedules","weather maps"],"Tap drill charts list drill sizes.")
H("817.d.3.B",4,"A tap drill chart tells a machinist:","what drill size to use before tapping a thread",["the price of the tap","the shop's hours","the color of the part"],"The chart matches drill to tap.")
H("817.d.4.A",3,"A student checks that guards are in place on a lathe, ties back long hair and keeps the chuck key out of the chuck before starting. She is practicing:","safety while running equipment commonly employed in machine shops",["horseplay","speed-running","shortcuts"],"Machine shop safety habits.")
H("817.d.4.A",4,"A chuck key should never be left in the chuck because it:","can be thrown out at high speed when the spindle starts",["gets dirty","looks messy","cools the part"],"Thrown keys cause injuries.")
H("817.d.4.B",3,"A student sorts used coolant, oily rags and spent solvent into labeled containers instead of the regular trash. She is:","identifying and properly disposing of environmentally hazardous materials",["hiding waste","ignoring waste","mixing waste"],"Hazardous materials need proper disposal.")
H("817.d.4.B",4,"Used oily rags in a machine shop should be placed in:","an approved, closed metal safety can",["a plastic bag in the trash","an open cardboard box","a heap on the floor"],"They can self-ignite.")
H("817.d.4.C",3,"A class loads a G-code program into a small CNC mill, sets the work offset and runs it in single-block mode to watch each move. They are demonstrating knowledge of:","computer numerical control (CNC) operations",["hand crank only","manual drilling only","hand sanding only"],"CNC follows coded instructions.")
H("817.d.4.C",4,"Running a new CNC program in single-block mode lets the operator:","check each move before continuing",["skip the setup","run it faster","remove the guard"],"Safer first run.")
H("817.d.4.D",3,"A student reports on how 5-axis machining, automated tool changers and in-process probing may change what machinists do. She is demonstrating knowledge of:","emerging technologies that may affect the machining industry",["old tools only","traditional crafts only","school clubs"],"New technology changes jobs.")
H("817.d.4.D",4,"A probe mounted in a CNC spindle can:","measure a part on the machine",["cool the part","cut threads","clean chips"],"In-process measurement.")
H("817.d.4.E",3,"A shop heats a steel tool to a high temperature and quenches it to make it hard, then reheats it to a lower temperature to reduce brittleness. These steps are:","hardening and tempering",["painting and sanding","buffing and waxing","cutting and gluing"],"Heat treatments change hardness.")
H("817.d.4.E",4,"After hardening, steel is often tempered to:","reduce brittleness",["increase brittleness","change its color only","make it softer than before"],"Tempering relieves brittleness.")
H("817.d.4.F",3,"A student practices setting up a vise on a mill and writes up the process for a job-shadow with a local machine shop. She is applying:","technical knowledge and skills in a machine shop to career preparation",["games","cooking","painting"],"Skills are applied in a career setting.")
H("817.d.4.F",4,"A job-shadow day at a machine shop helps a student by:","showing real working conditions and skills employers want",["replacing school","hiding the job","avoiding safety"],"Real-world exposure.")
H("817.d.4.G",3,"A class sorts samples into steel, aluminum, brass and plastics such as nylon and acetal and notes how each cuts. They are identifying:","basic metallic and non-metallic materials",["spices","fabrics","fruits"],"Metals and plastics are machined.")
H("817.d.4.G",4,"Of these, a non-metallic material often machined in a shop is:","nylon",["brass","aluminum","steel"],"Nylon is a plastic.")
H("817.d.4.H",3,"A student compares the type, structure, bond and typical use of aluminum oxide and silicon carbide wheels. She is comparing:","various abrasives",["various paints","various fabrics","various papers"],"Abrasives differ in type and use.")
H("817.d.4.H",4,"An aluminum oxide wheel is generally used to grind:","steel",["glass only","cast iron only","plastic only"],"Aluminum oxide suits steel.")
H("817.d.5.A",3,"A student puts on safety glasses, secures a part in a vise and clears the bench before filing and layout. She is using:","equipment commonly employed in bench work and layout in a safe manner",["equipment carelessly","equipment without training","equipment while distracted"],"Bench work safety.")
H("817.d.5.A",4,"When using a hand file, the safe practice is to:","use a handle on the tang",["use it without a handle","push it with a bare tang","use it as a hammer"],"A tang can injure.")
H("817.d.5.B",3,"A student files a steel block flat, then files a 30-degree angle on one end and a radius on a corner to match a template. She is developing the ability to:","use a file to cut flats, angles and radiuses",["paint surfaces","glue pieces","weld joints"],"Filing shapes metal by hand.")
H("817.d.5.B",4,"To keep a file cutting well, a worker should:","clean the teeth with a file card",["oil the teeth","hammer on it","wet it"],"A file card removes pins.")
H("817.d.5.C",3,"A student coats a part with layout dye, then uses a height gage and a scriber to mark lines from a drawing onto the metal. She is employing:","standard layout tools to transfer a part design to the actual piece",["a pencil only","guesswork","a stapler"],"Layout transfers print to metal.")
H("817.d.5.C",4,"Layout dye is applied to a metal surface so that:","scribed lines are easy to see",["it cools faster","it cuts faster","it gets harder"],"Contrast makes lines visible.")
H("817.d.5.D",3,"A student marks hole locations with a center punch, then drills each hole with a handheld drill. She is performing:","center punching and hand drilling of holes using an electric or air drill",["hand sanding","hand sewing","hand painting"],"Center punching starts the drill.")
H("817.d.5.D",4,"A center punch mark is made before drilling in order to:","keep the drill from wandering",["make the hole bigger","cool the drill","remove burrs"],"The mark guides the drill.")
H("817.d.5.E",3,"A student drills a 0.201-inch hole and then turns a 1/4-20 tap a half turn forward and a quarter turn back to cut internal threads. She is performing:","hand tapping of holes",["welding","painting","sanding"],"Hand taps cut internal threads.")
H("817.d.5.E",4,"When hand tapping, turning the tap back a little after each forward turn:","breaks the chip so it does not jam",["adds speed","adds heat","enlarges the hole"],"Chip breaking prevents tap breakage.")
H("817.d.5.F",3,"A student runs a straight reamer through a drilled hole with a drill to finish it to an exact size. She is performing:","hand reaming of holes using an electric or air hand drill",["hand sanding","hand sawing","hand welding"],"Reaming finishes holes to size.")
H("817.d.5.F",4,"A hole is reamed after drilling to:","improve its size and surface finish",["make it rougher","change its shape to a square","make it undersized"],"Reamers refine holes.")
H("817.d.5.G",3,"A student works from a print to lay out every hole and edge of a NIMS-style practice part and checks the layout against a gauge. She is developing:","a detailed layout part such as the NIMS Level 1 layout project",["a drawing contest","a sculpture","a quilt"],"Detailed layout practice.")
H("817.d.5.G",4,"The National Institute for Metalworking Skills (NIMS) sets:","industry-recognized standards and credentials for metalworking",["school lunch menus","sports rules","road laws"],"NIMS credentials.")
H("817.d.5.H",3,"A student completes a NIMS-style bench part by filing, drilling, reaming and tapping to the dimensions on the print. She is developing:","a detailed bench work part such as the NIMS Level 1 bench work project",["a poster","a poem","a recipe"],"Bench work project practice.")
H("817.d.5.H",4,"Before declaring a bench work part complete, the student should:","inspect it against the print dimensions",["paint it","hide it","discard the print"],"Inspect to print.")
H("817.d.5.I",3,"At the end of each class, a student sweeps chips, wipes the benches, puts tools back in their cabinet and wipes up coolant spills. She is employing:","basic housekeeping skills in a machine shop",["slow habits","careless habits","random habits"],"Housekeeping prevents hazards.")
H("817.d.5.I",4,"A clean, organized shop floor helps prevent:","slips, trips and lost tools",["all noise","all work","all heat"],"Housekeeping is safety.")

H("817.d.6.A",3,"A student wipes a micrometer's anvil and spindle faces, zeros it and handles it without dropping it before measuring a shaft. She is using:","equipment commonly used in precision measurement in a safe manner",["tools carelessly","tools without cleaning","tools as hammers"],"Care protects accuracy.")
H("817.d.6.A",4,"A micrometer should be stored with its measuring faces:","slightly apart and lightly oiled",["tightly clamped together","dropped in a drawer","left in the sun"],"Clamped faces can be damaged.")
H("817.d.6.B",3,"A quality technician lists the features to be checked on a bracket, the tool for each, the tolerance and how many parts to sample. She is writing:","an inspection plan",["a menu","a poem","a game plan"],"An inspection plan defines what to measure.")
H("817.d.6.B",4,"An inspection plan for a machined part should list:","the features, tolerances and measuring tools",["the workers' hobbies","the weather","the lunch menu"],"Defines how to check quality.")
H("817.d.6.C",3,"To check a hole that must be 0.500 inch plus or minus 0.001 inch, a technician picks a bore gage rather than a ruler. She is identifying and selecting:","the required measuring instruments to conduct the inspection",["a random tool","the least accurate tool","no tool"],"Match tool precision to tolerance.")
H("817.d.6.C",4,"A good rule is that a measuring instrument should be at least how many times more precise than the tolerance being checked?","10 times",["2 times","the same","half"],"The 10-to-1 rule.")
H("817.d.6.D",3,"A shop plots the diameter of every tenth part on a chart with upper and lower limits to see when the process starts drifting. She is describing:","statistical process control",["a shopping list","a sports score","a weather report"],"SPC tracks stability.")
H("817.d.6.D",4,"The purpose of statistical process control is to:","detect process changes before bad parts are made",["delay production","hide errors","increase scrap"],"Monitor trends.")
H("817.d.7.A",3,"A student uses a tool post, a tailstock and a steady rest to hold and support a long shaft in the lathe. She is using:","accessories commonly implemented on and around a lathe in a safe manner",["kitchen tools","garden tools","sports gear"],"Lathe accessories support work.")
H("817.d.7.A",4,"A steady rest is used on a lathe to:","support a long, slender workpiece",["speed up the spindle","cool the tool","hold the chuck key"],"Prevents deflection.")
H("817.d.7.B",3,"A student weighs the slower setup and the ability to center odd-shaped parts of a four-jaw chuck against the speed of a three-jaw chuck. She is analyzing:","the advantages and disadvantages of a four-jaw independent chuck and a three-jaw chuck",["colors","sizes of shoes","flavors"],"Compare chucks for each job.")
H("817.d.7.B",4,"A four-jaw independent chuck is the better choice for holding:","square or irregular parts that must be centered precisely",["only round stock quickly","only paper","only wood"],"Each jaw moves separately.")
H("817.d.7.C",3,"A student sets a dial indicator on a part in a four-jaw chuck and adjusts the jaws until the needle moves no more than 0.003 inch total. She is:","indicating a part in a four-jaw independent chuck within .003 inch total indicator reading",["painting the chuck","oiling the chuck","guessing"],"Tight TIR gives accuracy.")
H("817.d.7.C",4,"TIR on a dial indicator stands for:","total indicator reading",["total internal radius","time in rotation","tool inside reading"],"TIR measures runout.")
H("817.d.7.D",3,"A student labels the headstock, tailstock, carriage, cross slide, compound rest and spindle on a drawing of a lathe. She is identifying and describing:","the components of a lathe",["parts of a bicycle","parts of a loom","parts of a piano"],"Lathe parts have functions.")
H("817.d.7.D",4,"The part of a lathe that holds the cutting tool and moves along the bed is the:","carriage",["tailstock","spindle","chuck key"],"The carriage carries the tool.")
H("817.d.7.E",3,"A student picks a live center, a drill chuck, a boring bar and a knurling tool for different lathe jobs. She is identifying and using:","accessories and tooling for turning operations",["art supplies","yard tools","music gear"],"Turning uses many accessories.")
H("817.d.7.E",4,"A knurling tool on a lathe is used to:","press a textured pattern into a part for grip",["cut threads","drill holes","weld pieces"],"Knurls improve grip.")
H("817.d.7.F",3,"A student bores a hole to size, chamfers the edge, cuts a 1/2-13 thread and parts off the finished piece. She is demonstrating:","standard turning operations such as boring, chamfering, cutting threads and parting",["only sanding","only painting","only sewing"],"Standard lathe operations.")
H("817.d.7.F",4,"Parting on a lathe means:","cutting a finished piece off the stock",["polishing a surface","drilling a hole","knurling a surface"],"Parting separates the piece.")
H("817.d.7.G",3,"A student lists the steps, tools, speeds, feeds and depths of cut that will be used to turn a stepped shaft, in order. She is writing:","a detailed process plan for turning",["a story","a speech","a letter"],"A plan sequences operations.")
H("817.d.7.G",4,"A good process plan for turning lists the operations:","in the sequence they will be performed",["alphabetically","randomly","by tool color"],"Sequence matters.")
H("817.d.7.H",3,"A student turns a chuck-style practice part with several diameters, a thread and a groove to NIMS-style print dimensions. She is developing:","a detailed turning part such as the NIMS Level 1 turning project",["a poster","a poem","a recipe"],"Turning project practice.")
H("817.d.7.H",4,"After turning a part, a student checks that it meets the print by:","measuring each dimension with the right gauge",["looking at it","guessing","skipping inspection"],"Inspect to print.")
H("817.d.7.I",3,"After each class a student cleans the chips from the ways, wipes down the machine and puts a few drops of way oil on the slides. She is employing:","basic preventative maintenance on the lathe",["careless use","slow work","rough use"],"Maintenance extends machine life.")
H("817.d.7.I",4,"Lubricating the ways of a lathe regularly helps to:","reduce wear and keep movement smooth",["increase friction","speed up rust","slow the spindle"],"Lubrication reduces wear.")
H("817.d.8.A",3,"A student clamps a part in a vise, wears safety glasses and keeps hands away from the cutter while a mill runs. She is using:","equipment commonly used with a milling machine in a safe manner",["horseplay","speed shortcuts","bare hands near the cutter"],"Mill safety.")
H("817.d.8.A",4,"Chips from a milling machine should be cleared with:","a brush or a chip hook, not bare hands",["bare hands","a rag while the machine runs","compressed air at people"],"Chips are sharp and hot.")
H("817.d.8.B",3,"A student compares clamping a plate directly to the table, using a vise and using a fixture plate, noting the setup time and accuracy of each. She is analyzing:","the advantages and disadvantages of various work holding methods",["paint colors","fabric choices","food types"],"Each method has tradeoffs.")
H("817.d.8.B",4,"A milling vise is best for holding:","small to medium parts with parallel sides",["very large castings","paper","fabric"],"Vises grip parallel faces.")
H("817.d.8.C",3,"A student contrasts the roles of an end mill holder, a boring head, a rotary table and a dividing head. She is contrasting:","various ancillary tools used on milling machines",["kitchen tools","garden tools","art tools"],"Ancillary tools add capability.")
H("817.d.8.C",4,"A rotary table on a milling machine is used to:","machine arcs and circular patterns",["measure temperature","clean chips","hold paper"],"Rotary tables index and rotate work.")
H("817.d.8.D",3,"A student identifies the column, knee, saddle, table, quill and spindle on a diagram of a vertical mill. She is identifying:","the components of a milling machine and their functions",["parts of a bicycle","parts of a camera","parts of a piano"],"Mill components.")
H("817.d.8.D",4,"The component of a vertical mill that holds the cutter and rotates is the:","spindle",["saddle","knee","table"],"The spindle turns the tool.")
H("817.d.8.E",3,"A student uses a dial test indicator on the spindle and adjusts the head until the reading is the same at two points across the table. She is:","tramming in the head of a vertical milling machine",["painting the mill","oiling the vise","guessing"],"Tramming squares the head.")
H("817.d.8.E",4,"A mill head is trammed so that:","the spindle is square to the table",["the table is wet","the vise is closed","the oil is full"],"Tramming ensures accuracy.")
H("817.d.8.F",3,"A student sets a workpiece in a milling vise, taps it down on parallels and checks the face with a dial indicator before cutting. She is:","locating and setting a workpiece in a milling vise using a dial indicator",["painting the vise","hammering the part flat","guessing"],"Indicators verify setup.")
H("817.d.8.F",4,"A reason to indicate a part in a vise is to:","confirm it is square and positioned correctly",["make it hot","make it dirty","make it noisy"],"Indicating confirms accuracy.")
H("817.d.8.G",3,"A student mills all six faces of an aluminum block so that opposite faces are parallel and adjacent faces are square, to within a few thousandths. She is developing:","a square block in the milling machine to close tolerances",["a round ball","a triangle","a ring"],"Square block practice.")
H("817.d.8.G",4,"After milling a block square, the student checks that adjacent faces are square by using:","a machinist's square or indicator",["a ruler only","a scale only","her eyes only"],"Check squareness with a gauge.")
H("817.d.8.H",3,"A student spot drills, drills, reams and counterbores holes in a plate at coordinates from the print. She is demonstrating:","various hole-making activities such as spot drilling, drilling, reaming and boring",["only sanding","only painting","only sewing"],"Hole-making operations.")
H("817.d.8.H",4,"A spot drill is used before a twist drill in order to:","start an accurate hole location",["finish a hole","cut threads","remove burrs"],"Spot drills prevent wander.")
H("817.d.8.I",3,"A student takes a cut with the cutter turning against the feed and then with it, and mills a slot and a pocket in an aluminum plate. She is demonstrating:","various milling activities such as climb milling, conventional milling, slotting and pocketing",["only painting","only gluing","only sewing"],"Milling strategies.")
H("817.d.8.I",4,"In climb milling, the cutter teeth rotate:","with the direction of the feed",["against the feed","sideways","upward only"],"Climb milling cuts with the feed.")
H("817.d.8.J",3,"A student writes the sequence of operations for milling a bracket, including the cutter size, speeds, feeds and depth of cut for each pass. She is writing:","a detailed process plan for milling, including feeds, speeds and tooling",["a poem","a letter","a note"],"Process plans define milling.")
H("817.d.8.J",4,"A process plan for a mill job should include the:","tools, speeds, feeds and order of operations",["worker's age","weather","price of lunch"],"Plan the details.")
H("817.d.8.K",3,"A student mills a practice part with pockets, slots, holes and a contour to NIMS-style dimensions. She is developing:","a detailed milling part such as the NIMS Level 1 milling part",["a poster","a poem","a quilt"],"Milling project practice.")
H("817.d.8.K",4,"Before removing a milled part from the vise, a good habit is to:","check that critical features are within tolerance",["skip inspection","discard the print","hide the part"],"Check before unclamping.")
H("817.d.8.L",3,"After a mill job, a student brushes the chips off the table, wipes the machine, checks the coolant level and oils the ways. She is employing:","basic preventative maintenance on the milling machine",["careless use","speed use","rough use"],"Maintenance keeps machines accurate.")
H("817.d.8.L",4,"Keeping a mill's table and ways clean and lubricated helps to:","prevent wear and keep it accurate",["speed rust","increase friction","hide problems"],"Clean, lubricated machines last.")
H("817.d.8.E",3,"Before running a surface grinder, a student checks the wheel for cracks, stands to the side during the first start-up and wears eye protection. She is using:","proper safety procedures for surface grinding operations",["no guards","bare hands","no eye protection"],"Surface grinding safety.")
H("817.d.8.E",4,"A new grinding wheel should be started up:","with guards in place and the operator out of line with the wheel",["with the guard off","with the operator in front","at double speed"],"Ring test and safe startup.")
H("817.d.9.A",3,"A student uses a band saw, a pedestal grinder and a drill press, following the posted rules for each. She is using:","support equipment commonly found in a machine shop in a safe manner",["equipment carelessly","equipment without training","equipment while rushed"],"Support equipment safety.")
H("817.d.9.A",4,"Before using the pedestal grinder, a worker should:","adjust the tool rest close to the wheel",["move the rest far away","remove the guard","wear loose gloves"],"A narrow gap prevents jamming.")
H("817.d.9.B",3,"A student picks a grinding wheel for sharpening a drill bit, checking the grit, grade and the rated speed against the grinder's RPM. She understands:","basic pedestal grinder functions such as wheel selection",["bike pedals","sewing needles","cooking pans"],"Wheel selection matters.")
H("817.d.9.B",4,"A grinding wheel should never be used at a speed greater than:","its maximum rated speed",["its color","its price","its weight"],"Overspeed can cause bursting.")
